  EXECUTING_SNAPSHOT = "executing_snapshot",
  CANT_EXECUTE_SNAPSHOT = "cant_execute_snapshot",
  WITHDRAWING_CHALLENGE_DEPOSIT = "withdrawing_challenge_deposit",
